class Solution {
    private int totalTilt = 0;

    public int findTilt(TreeNode root) {
        totalTilt = 0;
        subtreeSum(root);
        return totalTilt;
    }

    private int subtreeSum(TreeNode node) {
        if (node == null) return 0;
        int leftSum = subtreeSum(node.left);
        int rightSum = subtreeSum(node.right);
        totalTilt += Math.abs(leftSum - rightSum);
        return node.val + leftSum + rightSum;
    }
}

class Solution {
    public int findTilt(TreeNode root) {
        if (root == null) return 0;
        int totalTilt = 0;
        java.util.Map<TreeNode, Integer> sumMap = new java.util.HashMap<>();
        java.util.Deque<TreeNode> stack = new java.util.ArrayDeque<>();
        java.util.Deque<TreeNode> output = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            output.push(node);
            if (node.left != null) stack.push(node.left);
            if (node.right != null) stack.push(node.right);
        }
        while (!output.isEmpty()) {
            TreeNode node = output.pop();
            int leftSum = node.left != null ? sumMap.get(node.left) : 0;
            int rightSum = node.right != null ? sumMap.get(node.right) : 0;
            totalTilt += Math.abs(leftSum - rightSum);
            sumMap.put(node, node.val + leftSum + rightSum);
        }
        return totalTilt;
    }
}
